// app/books/[id]/page.tsx
import { notFound } from 'next/navigation';

export default async function BookPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) notFound();
  return <h1>{book.title}</h1>;
}

// app/api/books/route.ts  (runs on the server only)
export async function GET(request: Request) {
  const q = new URL(request.url).searchParams.get('q') ?? '';
  const res = await fetch(`https://api.example.com/search?q=${encodeURIComponent(q)}`, {
    headers: { Authorization: `Bearer ${process.env.BOOKS_API_KEY}` },
  });
  if (!res.ok) return Response.json({ error: 'Lookup failed' }, { status: 502 });
  const data = await res.json();
  return Response.json(data.items.map((b: { id: string; title: string }) => ({ id: b.id, title: b.title })));
}
